const listProjectsByWorkspaceAliasWithStats = `-- name: ListProjectsByWorkspaceAliasWithStats :many
SELECT p.id, p.created_at, p.updated_at, p.deleted_at, p.name, p.workspace_id, p.avatar,
       COUNT(t.id)::int AS task_count,
       COALESCE(SUM(t.estimation), 0)::int AS total_estimation
FROM projects p
INNER JOIN project_users pu ON pu.project_id = p.id AND pu.user_id = $1
LEFT JOIN tasks t ON t.project_id = p.id AND t.deleted_at IS NULL
  AND ($2::timestamptz IS NULL OR COALESCE(t.end_date, t.start_date, t.created_at) >= $2::timestamptz)
  AND ($3::timestamptz IS NULL OR COALESCE(t.start_date, t.end_date, t.created_at) <= $3::timestamptz)
WHERE p.workspace_id = $4::uuid AND p.deleted_at IS NULL
GROUP BY p.id, p.created_at, p.updated_at, p.deleted_at, p.name, p.workspace_id, p.avatar
ORDER BY p.name
LIMIT $6::int OFFSET $5::int
`

