const upsertProjectUser = `-- name: UpsertProjectUser :one
INSERT INTO project_users (project_id, user_id, role)
VALUES ($1, $2, $3::project_role)
ON CONFLICT (project_id, user_id) DO UPDATE
SET role = EXCLUDED.role
RETURNING project_id, user_id, role
`

type UpsertProjectUserParams struct {
	ProjectID pgtype.UUID `json:"project_id"`
	UserID    pgtype.UUID `json:"user_id"`
	Column3   ProjectRole `json:"column_3"`
}

func (q *Queries) UpsertProjectUser(ctx context.Context, arg UpsertProjectUserParams) (ProjectUser, error) {
	row := q.db.QueryRow(ctx, upsertProjectUser, arg.ProjectID, arg.UserID, arg.Column3)
	var i ProjectUser
	err := row.Scan(&i.ProjectID, &i.UserID, &i.Role)
	return i, err
}
